import type { SceneDrawing } from '../scene-drawing.ts';
import { documentImageBudget } from '../../platform/main-images.ts';
import { trackPixelSource } from '../../platform/pixel-memory.ts';
import { assetMaterialCatalog } from '../asset-material-catalog.ts';
import { createAssetMaterials } from '../asset-materials.ts';
import { drawMaterialStamp } from '../scene-material.ts';
import { retireSceneTexture } from '../texture-revision.ts';
import type { SceneMaterial } from '../scene-frame.ts';
import type { Palette } from '../palette.ts';
import type { BladeStyle } from './types.ts';
import {
  nextVisibleFrame,
  paceTextureUploads,
  materialTextureUploads,
  type TextureUpload,
} from '../texture-upload.ts';
import {
  BLADE_RECIPES,
  BLADE_PROFILE_FRAMES,
  HILT_FRAMES,
  GUARD_PARTS,
  SPECIAL_FRAMES,
} from './blade-recipes.ts';
type Family = 'blades' | 'hilts' | 'special';
type MapKind = 'normal' | 'surface' | 'emissive';
type SourceKind = Family | MapKind;
type Frame = readonly [number, number, number, number];
const bladePack = assetMaterialCatalog.find(
  (pack) => pack.sourcePath === 'src/rendering/figures/assets/blade-profile-atlas.png',
)!;
const SOURCES: Record<Exclude<SourceKind, 'emissive'>, string> & { emissive?: string } = {
  blades: new URL('./assets/blade-pbr/blade-profile-atlas_diffuse.webp', import.meta.url).href,
  normal: new URL('./assets/blade-pbr/blade-profile-atlas_normal.webp', import.meta.url).href,
  surface: new URL('./assets/blade-pbr/blade-profile-atlas_surface.webp', import.meta.url).href,
  emissive: bladePack.maps.emissive,
  hilts: new URL('./assets/handle-guard-atlas.webp', import.meta.url).href,
  special: new URL('./assets/special-weapons-atlas.webp', import.meta.url).href,
};
/** Instance-owned modular weapon cache. Caller owns effects and local figure transforms. */
export function createInkSwordRenderer(doc: Document) {
  const fittings = createAssetMaterials<string>(doc, { hilts: SOURCES.hilts });
  const compactSpecial = documentImageBudget(doc) <= 256 * 1024 * 1024;
  const regularMaterials = new Map<string, SceneMaterial>();
  const regularPlanes = new Set<HTMLCanvasElement>();
  let regularCompacted = false,
    regularCompaction: Promise<boolean> | undefined;
  const specialMaterials = new Map<string, SceneMaterial>();
  const specialParts = new Map<string, HTMLCanvasElement>();
  const specialPlanes = new Set<HTMLCanvasElement>();
  let specialCompaction: Promise<boolean> | undefined;
  let specialCompacted = false;
  const materials = new Map<number, SceneMaterial>();
  const surface = trackPixelSource(doc, doc.createElement('img'), 'decoded');
  const images = new Map<SourceKind, HTMLImageElement>(),
    loaded = new Set<SourceKind>(),
    cache = new Map<string, HTMLCanvasElement>(),
    finish = new Set<() => void>();
  let disposed = false,
    specialRequested = false;
  const preparations = new Map<string, Promise<void>>();
  const sourcePreparations = new Map<SourceKind, Promise<void>>();
  const partPreparations = new Map<string, Promise<boolean>>();
  const preparation = new AbortController();
  const pbrReady = () =>
    !disposed &&
    ['normal', 'surface'].every((kind) => loaded.has(kind as MapKind)) &&
    (!SOURCES.emissive || loaded.has('emissive'));
  function prepare(ids: readonly string[] = Object.keys(BLADE_RECIPES)): Promise<void> {
    if (disposed) return Promise.resolve();
    const special = ids.some((id) => BLADE_RECIPES[id]?.special);
    const key = special ? 'all' : 'base';
    const prior = preparations.get(key);
    if (prior) return prior;
    specialRequested ||= special;
    fittings.select({
      ...(regularCompacted ? {} : { hilts: SOURCES.hilts }),
      ...(specialRequested && !specialCompacted ? { special: SOURCES.special } : {}),
    });
    const pending = Promise.all(
      (Object.keys(SOURCES) as SourceKind[])
        .filter((kind) => SOURCES[kind] && (kind !== 'special' || special))
        .map((family) => {
          const prior = sourcePreparations.get(family);
          if (prior) return prior;
          const loading = new Promise<void>((resolve) => {
            const im =
              family === 'surface'
                ? surface
                : trackPixelSource(doc, doc.createElement('img'), 'decoded');
            images.set(family, im);
            const done = () => {
              im.onload = null;
              im.onerror = null;
              finish.delete(done);
              resolve();
            };
            finish.add(done);
            im.onload = () => {
              const [w, h] = family === 'special' ? [1774, 887] : [1254, 1254];
              if (!disposed && im.naturalWidth === w && im.naturalHeight === h) loaded.add(family);
              done();
            };
            im.onerror = done;
            im.src = SOURCES[family]!;
          });
          sourcePreparations.set(family, loading);
          return loading;
        }),
    ).then(async () => {
      await fittings.prepare();
    });
    preparations.set(key, pending);
    return pending;
  }
  function fittingStamp(
    g: SceneDrawing,
    family: 'hilts' | 'special',
    frame: Frame,
    source: HTMLCanvasElement,
    x: number,
    y: number,
    width: number,
    height: number,
  ) {
    const material = fittingMaterial(family, frame);
    if (material)
      drawMaterialStamp(g, { texture: { source, revision: 0 }, material, x, y, width, height });
    else g.drawImage(source, x, y, width, height);
  }
  function part(family: Family, frame: Frame, tint?: string): HTMLCanvasElement | null {
    const key = family + ':' + frame.join(',') + ':' + (tint || '');
    const prepared = specialParts.get(key);
    if (prepared) return prepared;
    const prior = cache.get(key);
    if (prior) {
      cache.delete(key);
      cache.set(key, prior);
      return prior;
    }
    const im = images.get(family);
    if (!im) return null;
    const [sx, sy, sw, sh] = frame,
      c = trackPixelSource(doc, doc.createElement('canvas'), 'canvas'),
      s = Math.min(1, (family === 'blades' ? 1024 : 512) / Math.max(sw, sh));
    c.width = Math.max(1, Math.round(sw * s));
    c.height = Math.max(1, Math.round(sh * s));
    const g = c.getContext('2d', { willReadFrequently: true });
    if (!g) return null;
    g.drawImage(im, sx, sy, sw, sh, 0, 0, c.width, c.height);
    const data = g.getImageData(0, 0, c.width, c.height);
    // The originals retain near-transparent generator fringe. Clean only bounded cached cutouts.
    for (let i = 3; i < data.data.length; i += 4) if (data.data[i]! <= 16) data.data[i] = 0;
    g.putImageData(data, 0, 0);
    if (tint) {
      g.globalCompositeOperation = 'source-atop';
      g.globalAlpha = 0.48;
      g.fillStyle = tint;
      g.fillRect(0, 0, c.width, c.height);
    }
    cache.set(key, c);
    if (cache.size > 80) {
      const first = cache.keys().next().value!,
        old = cache.get(first)!;
      retireSceneTexture(old, true);
      old.width = old.height = 0;
      cache.delete(first);
    }
    return c;
  }
  function fittingMaterial(family: 'hilts' | 'special', frame: Frame) {
    return family === 'special' && specialCompacted
      ? (specialMaterials.get(frame.join(',')) ?? null)
      : family === 'hilts' && regularCompacted
        ? (regularMaterials.get('hilts:' + frame.join(',')) ?? null)
        : fittings.material(family, frame);
  }
  function bladeMaterial(frame: Frame): SceneMaterial | null {
    if (regularCompacted) return regularMaterials.get('blades:' + frame.join(',')) ?? null;
    return {
      normal: { source: images.get('normal')!, revision: 0, frame },
      surface: { source: surface, revision: 0, frame },
      ...(images.has('emissive')
        ? { emissive: { source: images.get('emissive')!, revision: 0, frame } }
        : {}),
      normalY: -1,
      lighting: 1,
      depth: 0,
      fog: 0,
      fogColor: [0.53, 0.51, 0.47],
    };
  }
  /** Finite regular map planes preserve original colour cutouts and authored geometry. */
  function compactRegularMaterials(): Promise<boolean> {
    if (!compactSpecial || regularCompacted) return Promise.resolve(true);
    return (regularCompaction ??= (async () => {
      const frames: { family: 'blades' | 'hilts'; frame: Frame }[] = [
        ...Object.values(BLADE_PROFILE_FRAMES).map((profile) => ({
          family: 'blades' as const,
          frame: profile.frame,
        })),
        ...Object.values(HILT_FRAMES).map((frame) => ({ family: 'hilts' as const, frame })),
        ...Object.values(GUARD_PARTS).map((guard) => ({
          family: 'hilts' as const,
          frame: guard.frame,
        })),
      ];
      let complete = true;
      const ready = await paceTextureUploads(frames, preparation.signal, {
        nextFrame: (signal) => nextVisibleFrame(doc, signal),
        ready: () => !disposed && !doc.hidden,
        generation: () => 0,
        now: () => doc.defaultView!.performance.now(),
        upload: ({ family, frame }) => {
          const original =
            family === 'blades' ? bladeMaterial(frame) : fittings.material('hilts', frame);
          if (!original) {
            complete = false;
            return;
          }
          const material = { ...original };
          const scale = Math.min(
            1,
            (family === 'blades' ? 512 : 256) / Math.max(frame[2], frame[3]),
          );
          for (const kind of ['normal', 'surface', 'emissive'] as const) {
            const input = original[kind];
            if (!input) continue;
            const plane = trackPixelSource(doc, doc.createElement('canvas'), 'canvas');
            plane.width = Math.max(1, Math.round(frame[2] * scale));
            plane.height = Math.max(1, Math.round(frame[3] * scale));
            regularPlanes.add(plane);
            plane
              .getContext('2d')!
              .drawImage(input.source, ...frame, 0, 0, plane.width, plane.height);
            material[kind] = {
              source: plane,
              revision: 0,
              frame: [0, 0, plane.width, plane.height],
            };
          }
          regularMaterials.set(family + ':' + frame.join(','), material);
        },
      });
      if (!ready || !complete || disposed) return false;
      regularCompacted = true;
      materials.clear();
      for (const kind of ['normal', 'surface', 'emissive'] as const) {
        const image = images.get(kind);
        if (image) {
          retireSceneTexture(image, true);
          image.removeAttribute('src');
          image.width = image.height = 0;
        }
      }
      fittings.select(
        specialRequested && !specialCompacted ? { special: SOURCES.special } : {},
        true,
      );
      return true;
    })());
  }
  /** Keep the finite special catalogue independent of the ordinary tint LRU. */
  function compactSpecialParts(): Promise<boolean> {
    if (!compactSpecial || specialCompacted) return Promise.resolve(true);
    return (specialCompaction ??= (async () => {
      let complete = true;
      const prepared = await paceTextureUploads(Object.values(SPECIAL_FRAMES), preparation.signal, {
        nextFrame: (signal) => nextVisibleFrame(doc, signal),
        ready: () => !disposed && !doc.hidden,
        generation: () => 0,
        now: () => doc.defaultView!.performance.now(),
        upload: (frame) => {
          const colour = part('special', frame);
          const original = fittings.material('special', frame);
          if (!colour || !original) {
            complete = false;
            return;
          }
          const material: SceneMaterial = { ...original };
          for (const kind of ['normal', 'surface', 'emissive'] as const) {
            const texture = original[kind];
            if (!texture) continue;
            const plane = trackPixelSource(doc, doc.createElement('canvas'), 'canvas');
            plane.width = colour.width;
            plane.height = colour.height;
            specialPlanes.add(plane);
            const context = plane.getContext('2d');
            if (!context) {
              complete = false;
              return;
            }
            context.drawImage(
              texture.source,
              frame[0],
              frame[1],
              frame[2],
              frame[3],
              0,
              0,
              plane.width,
              plane.height,
            );
            material[kind] = {
              source: plane,
              revision: 0,
              frame: [0, 0, plane.width, plane.height],
            };
          }
          specialMaterials.set(frame.join(','), material);
          const tints = frame === SPECIAL_FRAMES.pan ? [undefined, '#c8a650'] : [undefined];
          for (const tint of tints) {
            const colourPart = part('special', frame, tint);
            if (!colourPart) {
              complete = false;
              return;
            }
            const key = 'special:' + frame.join(',') + ':' + (tint || '');
            specialParts.set(key, colourPart);
            cache.delete(key);
          }
        },
      });
      if (!prepared || !complete || disposed) return false;
      specialCompacted = true;
      const raw = images.get('special');
      if (raw) {
        retireSceneTexture(raw, true);
        raw.removeAttribute('src');
        images.delete('special');
      }
      fittings.select(regularCompacted ? {} : { hilts: SOURCES.hilts }, true);
      return true;
    })());
  }
  /** Prepare the finite catalogue before presentation; draw uses these same cutouts. */
  function prepareParts(ids: readonly string[] = Object.keys(BLADE_RECIPES)): Promise<boolean> {
    if (disposed) return Promise.resolve(false);
    const selected = [...new Set(ids)].sort();
    if (selected.some((id) => !Object.hasOwn(BLADE_RECIPES, id))) return Promise.resolve(false);
    const key = selected.join(':');
    const prior = partPreparations.get(key);
    if (prior) return prior;
    const pendingParts = prepare(selected).then(async () => {
      if (disposed || !ready(selected)) return false;
      if (selected.some((id) => BLADE_RECIPES[id]?.special) && !(await compactSpecialParts()))
        return false;
      if (!(await compactRegularMaterials())) return false;
      const stamps: { family: Family; frame: Frame; tint?: string }[] = [];
      for (const id of selected) {
        const recipe = BLADE_RECIPES[id]!;
        if (recipe.special) {
          stamps.push({ family: 'special', frame: SPECIAL_FRAMES[recipe.special] });
          if (recipe.special === 'pan')
            stamps.push({ family: 'special', frame: SPECIAL_FRAMES.pan, tint: '#c8a650' });
        } else {
          stamps.push(
            {
              family: 'blades',
              frame: BLADE_PROFILE_FRAMES[recipe.profile]!.frame,
              tint: recipe.tint,
            },
            { family: 'hilts', frame: HILT_FRAMES[recipe.hilt]!, tint: recipe.hiltTint },
            { family: 'hilts', frame: GUARD_PARTS[recipe.guard]!.frame },
          );
        }
      }
      let complete = true;
      return paceTextureUploads(stamps, preparation.signal, {
        nextFrame: (signal) => nextVisibleFrame(doc, signal),
        ready: () => !disposed && !doc.hidden,
        generation: () => 0,
        now: () => doc.defaultView!.performance.now(),
        upload: ({ family, frame, tint }) => {
          complete = !!part(family, frame, tint) && complete;
        },
      }).then((prepared) => prepared && complete);
    });
    partPreparations.set(key, pendingParts);
    return pendingParts;
  }
  function ready(ids: readonly string[] = specialRequested ? Object.keys(BLADE_RECIPES) : []) {
    const special = ids.some((id) => BLADE_RECIPES[id]?.special);
    return (
      (Object.keys(SOURCES) as SourceKind[])
        .filter((kind) => SOURCES[kind] && kind !== 'special')
        .every((kind) => loaded.has(kind)) &&
      pbrReady() &&
      (regularCompacted || fittings.ready('hilts')) &&
      (!special || (loaded.has('special') && (specialCompacted || fittings.ready('special'))))
    );
  }
  async function prepareUploads(
    ids: readonly string[],
    signal: AbortSignal,
  ): Promise<TextureUpload[] | undefined> {
    if (signal.aborted || !(await prepareParts(ids)) || signal.aborted || disposed) return;
    const uploads: TextureUpload[] = [];
    const add = (family: Family, frame: Frame, tint?: string) => {
      const image = part(family, frame, tint);
      if (!image) return false;
      const material = family === 'blades' ? bladeMaterial(frame) : fittingMaterial(family, frame);
      uploads.push(...materialTextureUploads({ source: image, revision: 0 }, material));
      return true;
    };
    for (const id of new Set(ids)) {
      const recipe = BLADE_RECIPES[id]!;
      if (recipe.special) {
        if (!add('special', SPECIAL_FRAMES[recipe.special])) return;
        if (recipe.special === 'pan' && !add('special', SPECIAL_FRAMES.pan, '#c8a650')) return;
      } else if (
        !add('blades', BLADE_PROFILE_FRAMES[recipe.profile]!.frame, recipe.tint) ||
        !add('hilts', HILT_FRAMES[recipe.hilt]!, recipe.hiltTint) ||
        !add('hilts', GUARD_PARTS[recipe.guard]!.frame)
      )
        return;
    }
    return uploads;
  }
  function draw(
    g: SceneDrawing,
    gx: number,
    gy: number,
    ang: number,
    _C: Palette,
    bs?: BladeStyle | null,
    id = 'steel',
  ): boolean {
    const recipe = BLADE_RECIPES[id],
      length = bs?.len ?? 0.52;
    if (disposed || !recipe || ![gx, gy, ang, length].every(Number.isFinite) || length <= 0)
      return false;
    if (recipe.special ? !loaded.has('special') : !loaded.has('blades') || !loaded.has('hilts')) {
      void prepare([id]);
      return false;
    }
    // Resolve all required stamps before touching the caller's context.
    if (recipe.special) {
      const frame = SPECIAL_FRAMES[recipe.special],
        im = part('special', frame, recipe.special === 'pan' && bs?.gold ? '#c8a650' : undefined);
      if (!im) return false;
      g.save();
      try {
        g.translate(gx, gy);
        g.rotate(ang);
        if (bs?.alpha !== undefined) g.globalAlpha *= Math.max(0, Math.min(1, bs.alpha));
        if (recipe.special === 'beam') {
          const sx = 0.18 / (1400 - 331),
            sy = 0.045 / 195;
          fittingStamp(
            g,
            'special',
            frame,
            im,
            0.016 - (1400 - frame[0]) * sx,
            -(194 - frame[1]) * sy,
            frame[2] * sx,
            frame[3] * sy,
          );
        } else {
          const s = length / (1681 - 500);
          fittingStamp(
            g,
            'special',
            frame,
            im,
            -(500 - frame[0]) * s,
            -(584 - frame[1]) * s,
            frame[2] * s,
            frame[3] * s,
          );
        }
        return true;
      } finally {
        g.restore();
      }
    }
    const profile = BLADE_PROFILE_FRAMES[recipe.profile]!,
      hiltFrame = HILT_FRAMES[recipe.hilt]!,
      guard = GUARD_PARTS[recipe.guard]!;
    const blade = part('blades', profile.frame, recipe.tint),
      hilt = part('hilts', hiltFrame, recipe.hiltTint),
      tsuba = part('hilts', guard.frame);
    if (!blade || !hilt || !tsuba) return false;
    g.save();
    try {
      g.translate(gx, gy);
      g.rotate(ang);
      if (bs?.alpha !== undefined) g.globalAlpha *= Math.max(0, Math.min(1, bs.alpha));
      fittingStamp(g, 'hilts', hiltFrame, hilt, -0.15, -0.016, 0.158, 0.032);
      const scale = 0.062 / guard.frame[3];
      fittingStamp(
        g,
        'hilts',
        guard.frame,
        tsuba,
        0.008 - (guard.pivot[0] - guard.frame[0]) * scale,
        -(guard.pivot[1] - guard.frame[1]) * scale,
        guard.frame[2] * scale,
        guard.frame[3] * scale,
      );
      const dx = profile.tip[0] - profile.root[0],
        dy = profile.tip[1] - profile.root[1],
        tx = length - 0.016,
        ty = -length * 0.05,
        s = Math.hypot(tx, ty) / Math.hypot(dx, dy);
      g.translate(0.016, 0);
      g.rotate(Math.atan2(ty, tx) - Math.atan2(dy, dx));
      const x = -(profile.root[0] - profile.frame[0]) * s,
        y = -(profile.root[1] - profile.frame[1]) * s;
      if (pbrReady()) {
        let material = materials.get(recipe.profile);
        if (!material) {
          material = bladeMaterial(profile.frame)!;
          materials.set(recipe.profile, material);
        }
        drawMaterialStamp(g, {
          texture: { source: blade, revision: 0 },
          material,
          x,
          y,
          width: profile.frame[2] * s,
          height: profile.frame[3] * s,
        });
      } else g.drawImage(blade, x, y, profile.frame[2] * s, profile.frame[3] * s);
      return true;
    } finally {
      g.restore();
    }
  }
  return {
    prepare,
    prepareParts,
    prepareUploads,
    draw,
    get ready() {
      return ready();
    },
    snapshot: () => ({
      loaded: [...loaded],
      specialCompacted,
      regularCompacted,
      regularMapPixels: [...regularPlanes].reduce((n, c) => n + c.width * c.height, 0),
      specialPixels: [...specialPlanes, ...specialParts.values()].reduce(
        (n, c) => n + c.width * c.height,
        0,
      ),
      cachedParts: cache.size + specialParts.size,
      cachedPixels: [...cache.values(), ...specialParts.values()].reduce(
        (total, canvas) => total + canvas.width * canvas.height,
        0,
      ),
      pbrReady: pbrReady(),
      disposed,
    }),
    dispose() {
      if (disposed) return;
      disposed = true;
      preparation.abort();
      partPreparations.clear();
      preparations.clear();
      sourcePreparations.clear();
      fittings.dispose();
      materials.clear();
      for (const im of images.values()) {
        retireSceneTexture(im);
        im.onload = null;
        im.onerror = null;
        im.removeAttribute('src');
      }
      surface.width = surface.height = 0;
      for (const f of [...finish]) f();
      for (const c of [
        ...cache.values(),
        ...specialParts.values(),
        ...specialPlanes,
        ...regularPlanes,
      ]) {
        retireSceneTexture(c);
        c.width = c.height = 0;
      }
      regularMaterials.clear();
      regularPlanes.clear();
      specialMaterials.clear();
      specialParts.clear();
      specialPlanes.clear();
      cache.clear();
      images.clear();
      loaded.clear();
    },
  };
}
